#include <iostream>
using namespace std;

int main() {
    int a[5] = {5, 3, 8, 1, 4};
    int n = 5;
    for (int pass = 0; pass < n - 1; pass++) {
        for (int j = 0; j < n - 1 - pass; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
    for (int x : a) {
        cout << x << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[5] = {5, 3, 8, 1, 4};
    int n = 5;
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[m]) {
                m = j;
            }
        }
        int t = a[i];
        a[i] = a[m];
        a[m] = t;
    }
    for (int x : a) {
        cout << x << " ";
    }
    cout << endl;
    return 0;
}

